class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None

        self.aapl_red_streak = 0

        self.lots = {
            1: 0,
            2: 0
        }

        self.eligible_slot = 1
        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        required = list(self.symbols.values())

        if any(symbol not in data.Bars for symbol in required):
            return

        bars = {symbol: data.Bars[symbol] for symbol in required}

        spy_bar = bars[self.spy]
        aapl_bar = bars[self.aapl]

        current_spy_close = float(spy_bar.Close)
        current_aapl_close = float(aapl_bar.Close)

        self.spy_sma.Update(spy_bar.EndTime, current_spy_close)
        self.aapl_rsi.Update(aapl_bar.EndTime, current_aapl_close)

        if self.previous_aapl_close is not None:
            if current_aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if (
            self.spy_sma.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            spy_buy = (
                self.previous_spy_close <= self.previous_spy_sma
                and current_spy_close > float(self.spy_sma.Current.Value)
            )
            spy_sell = (
                self.previous_spy_close >= self.previous_spy_sma
                and current_spy_close < float(self.spy_sma.Current.Value)
            )
        else:
            spy_buy = False
            spy_sell = False

        aapl_buy = self.aapl_red_streak >= 3
        aapl_sell = self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60

        completed_round_trip = False

        if self.eligible_slot == 1:
            if self.lots[1] > 0 and spy_sell:
                self.LiquidateLot(1, self.spy)
                completed_round_trip = True

            if self.lots[1] == 0 and spy_buy:
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                quantity = floor(target_value / current_spy_close)

                if quantity > 0:
                    self.MarketOrder(self.spy, quantity, tag="Strategy A")
                    self.lots[1] = quantity

        elif self.eligible_slot == 2:
            if self.lots[2] > 0 and aapl_sell:
                self.LiquidateLot(2, self.aapl)
                completed_round_trip = True

            if self.lots[2] == 0 and aapl_buy:
                if self.Portfolio.Cash >= 20000:
                    quantity = floor(20000 / current_aapl_close)

                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity, tag="Strategy B")
                        self.lots[2] = quantity

        if completed_round_trip:
            self.eligible_slot = 2 if self.eligible_slot == 1 else 1

        self.previous_spy_close = current_spy_close
        self.previous_spy_sma = (
            float(self.spy_sma.Current.Value)
            if self.spy_sma.IsReady else None
        )
        self.previous_aapl_close = current_aapl_close

    def LiquidateLot(self, slot, symbol):
        quantity = self.lots[slot]

        if quantity > 0:
            self.MarketOrder(symbol, -quantity, tag=f"Liquidate Strategy {slot}")

        self.lots[slot] = 0
