                    self.MarketOrder(self.spy, -self.slot1_quantity)
                    self.slot1_quantity = 0
                    self.eligible_slot = 2

            elif self.eligible_slot == 2 and self.slot2_quantity > 0:
                if aapl_rsi_above_60:
                    self.MarketOrder(self.aapl, -self.slot2_quantity)
                    self.slot2_quantity = 0
                    self.eligible_slot = 1

            if self.eligible_slot == 1 and self.slot1_quantity == 0:
                if spy_crosses_above:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
